/** 1200x630 Open Graph & Twitter Card image for /shopify-va (Shopify commerce emerald + native system typography). */
export const OG_IMAGE_BASE64 = '';
let cachedBytes: Uint8Array<ArrayBuffer> | undefined;
export function ogImageBytes(): Uint8Array<ArrayBuffer> {
  if (!cachedBytes) {
    const binary = atob(OG_IMAGE_BASE64);
    const bytes = new Uint8Array(new ArrayBuffer(binary.length));
    for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
    cachedBytes = bytes;
  }
  return cachedBytes;
}
